// Package chaingen generates the chain-method wrappers of the public builders
// (SelectBuilder, InsertBuilder, UpdateBuilder, DeleteBuilder, WhereClause,
// HavingClause and Query[T]) from the exported methods of the internal query type
// in package db, so each builder only exposes the methods valid for its statement.
//
// It reads Go source only and never imports package db.
package chaingen

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/printer"
	"go/token"
	"path/filepath"
	"slices"
	"sort"
	"strings"
)

// OutFile is the generated file's name inside the db package directory.
const OutFile = "chain_gen.go"

const (
	kSelect = "select"
	kInsert = "insert"
	kUpdate = "update"
	kDelete = "delete"
	kWhere  = "where"
	kHaving = "having"
	kTyped  = "typed"
)

type target struct {
	name string // section label
	recv string // receiver as written in the method declaration
	acc  string // expression reaching the underlying query value
	ret  string // receiver variable returned by chain methods
}

var targets = map[string]target{
	kSelect: {"SelectBuilder", "s *SelectBuilder", "s.q", "s"},
	kInsert: {"InsertBuilder", "i *InsertBuilder", "i.q", "i"},
	kUpdate: {"UpdateBuilder", "u *UpdateBuilder", "u.q", "u"},
	kDelete: {"DeleteBuilder", "d *DeleteBuilder", "d.q", "d"},
	kWhere:  {"WhereClause", "w *WhereClause", "w.q", "w"},
	kHaving: {"HavingClause", "h *HavingClause", "h.q", "h"},
	kTyped:  {"Query[T]", "q *Query[T]", "q.b.q", "q"},
}

// order fixes the output order of the sections.
var order = []string{kSelect, kInsert, kUpdate, kDelete, kWhere, kHaving, kTyped}

// groups maps a method group to the builders that expose it.
var groups = map[string][]string{
	"common":     {kSelect, kInsert, kUpdate, kDelete},
	"returning":  {kInsert, kUpdate, kDelete},
	"allrows":    {kUpdate, kDelete},
	kWhere:       {kSelect, kUpdate, kDelete, kWhere, kTyped},
	kHaving:      {kSelect, kHaving, kTyped},
	"join":       {kSelect, kUpdate, kDelete, kTyped},
	"orderlimit": {kSelect, kUpdate, kDelete, kTyped},
	kSelect:      {kSelect, kTyped},
	"cte":        {kSelect, kInsert, kUpdate, kDelete, kTyped},
	"read":       {kSelect}, // terminal methods that do not return the query
}

var orderLimit = map[string]bool{
	"OrderBy": true, "OrderByDesc": true, "OrderByRaw": true, "Limit": true, "Take": true,
	"Latest": true, "Oldest": true, "InRandomOrder": true, "Reorder": true, "ReorderBy": true,
}

// skipped methods are written by hand on each builder.
var skipped = map[string]bool{"Clone": true, "When": true, "Unless": true, "Tap": true}

func groupOf(name string, chain bool) string {
	switch {
	case name == "Prefix" || name == "Err":
		return "common"
	case name == "Returning":
		return "returning"
	case name == "AllRows":
		return "allrows"
	case chain && (name == "With" || name == "WithRaw" || name == "WithRecursive"):
		return "cte"
	case !chain:
		return "read"
	case strings.HasPrefix(name, "Having") || strings.HasPrefix(name, "OrHaving"):
		return kHaving
	case strings.HasPrefix(name, "Where") || strings.HasPrefix(name, "OrWhere"):
		return kWhere
	case strings.Contains(name, "Join"):
		return "join"
	case orderLimit[name]:
		return "orderlimit"
	}
	return kSelect
}

type param struct {
	name, typ string
	variadic  bool
}

type method struct {
	name    string
	doc     []string
	params  []param
	results []string
	chain   bool
	group   string
}

func printExpr(fset *token.FileSet, e ast.Expr) string {
	var b bytes.Buffer
	if err := printer.Fprint(&b, fset, e); err != nil {
		panic(err)
	}
	return b.String()
}

// Generate returns the formatted contents of chain_gen.go for the package in dir.
func Generate(dir string) ([]byte, error) {
	methods, err := parseDir(dir)
	if err != nil {
		return nil, err
	}
	var body bytes.Buffer
	for _, key := range order {
		t := targets[key]
		for _, m := range methods {
			if !contains(groups[m.group], key) || (key == kTyped && !m.chain) {
				continue
			}
			src, err := render(t, m)
			if err != nil {
				return nil, fmt.Errorf("%s.%s: %w", t.name, m.name, err)
			}
			body.WriteString("\n" + src)
		}
	}
	var out bytes.Buffer
	out.WriteString("// Code generated by internal/chaingen; DO NOT EDIT.\n\npackage db\n")
	out.WriteString(importBlock(body.String()))
	out.Write(body.Bytes())
	return format.Source(out.Bytes())
}

// importBlock returns the import declaration the generated code needs.
func importBlock(body string) string {
	var code strings.Builder
	for _, line := range strings.Split(body, "\n") {
		if !strings.HasPrefix(line, "//") {
			code.WriteString(line + "\n")
		}
	}
	var imports []string
	for _, imp := range []struct{ sel, path string }{
		{"context.", "context"}, {"sql.", "database/sql"}, {"time.", "time"},
	} {
		if strings.Contains(code.String(), imp.sel) {
			imports = append(imports, fmt.Sprintf("\t%q\n", imp.path))
		}
	}
	if len(imports) == 0 {
		return ""
	}
	return "\nimport (\n" + strings.Join(imports, "") + ")\n"
}

// parseDir collects the exported *query methods of every non-test file in dir.
func parseDir(dir string) ([]method, error) {
	files, err := filepath.Glob(filepath.Join(dir, "*.go"))
	if err != nil {
		return nil, err
	}
	sort.Strings(files)
	fset := token.NewFileSet()
	var methods []method
	for _, f := range files {
		base := filepath.Base(f)
		if base == OutFile || strings.HasSuffix(base, "_test.go") {
			continue
		}
		file, err := parser.ParseFile(fset, f, nil, parser.ParseComments)
		if err != nil {
			return nil, err
		}
		for _, d := range file.Decls {
			if fn, ok := d.(*ast.FuncDecl); ok && isQueryMethod(fset, fn) {
				methods = append(methods, newMethod(fset, fn))
			}
		}
	}
	return methods, nil
}

func isQueryMethod(fset *token.FileSet, fn *ast.FuncDecl) bool {
	if fn.Recv == nil || len(fn.Recv.List) != 1 || !fn.Name.IsExported() || skipped[fn.Name.Name] {
		return false
	}
	return printExpr(fset, fn.Recv.List[0].Type) == "*query"
}

func newMethod(fset *token.FileSet, fn *ast.FuncDecl) method {
	m := method{name: fn.Name.Name}
	if fn.Doc != nil {
		for _, c := range fn.Doc.List {
			m.doc = append(m.doc, c.Text)
		}
	}
	m.params = paramsOf(fset, fn.Type.Params)
	if fn.Type.Results != nil {
		for _, fl := range fn.Type.Results.List {
			for range max(len(fl.Names), 1) {
				m.results = append(m.results, printExpr(fset, fl.Type))
			}
		}
	}
	m.chain = len(m.results) == 1 && m.results[0] == "*query"
	m.group = groupOf(m.name, m.chain)
	return m
}

func paramsOf(fset *token.FileSet, fields *ast.FieldList) []param {
	var out []param
	for _, fl := range fields.List {
		typ := printExpr(fset, fl.Type)
		variadic := false
		if el, ok := fl.Type.(*ast.Ellipsis); ok {
			variadic = true
			typ = printExpr(fset, el.Elt)
		}
		names := fl.Names
		if len(names) == 0 {
			names = []*ast.Ident{ast.NewIdent(fmt.Sprintf("a%d", len(out)))}
		}
		for _, nm := range names {
			out = append(out, param{nm.Name, typ, variadic})
		}
	}
	return out
}

func contains(list []string, s string) bool {
	return slices.Contains(list, s)
}

// callbackType is the public callback parameter of the group methods.
func callbackType(name string) (string, error) {
	switch {
	case strings.Contains(name, "Having"):
		return "HavingClause", nil
	case strings.Contains(name, "Where"):
		return "WhereClause", nil
	}
	return "", fmt.Errorf("no callback type for %s", name)
}

func render(t target, m method) (string, error) {
	var sig, args, pre []string
	recvVar := strings.Fields(t.recv)[0]
	for _, p := range m.params {
		if p.name == recvVar {
			// the parameter would shadow the receiver; the name is not part of the API
			if p.typ == "*query" {
				p.name = "sub"
			} else {
				p.name += "Arg"
			}
		}
		typ := p.typ
		arg := p.name
		switch {
		case typ == "*query":
			typ, arg = "*SelectBuilder", "sq("+p.name+")"
		case typ == "func(*query)":
			cb, err := callbackType(m.name)
			if err != nil {
				return "", err
			}
			typ = "func(*" + cb + ")"
			pre = append(
				pre,
				fmt.Sprintf(
					"var %[1]sFn func(*query)\n\tif %[1]s != nil {\n\t\t%[1]sFn = func(q *query) { %[1]s(&%[2]s{q: q}) }\n\t}",
					p.name,
					cb,
				),
			)
			arg = p.name + "Fn"
		case strings.Contains(typ, "query"):
			return "", fmt.Errorf("unsupported parameter type %s", typ)
		}
		if p.variadic {
			sig = append(sig, p.name+" ..."+typ)
			arg += "..."
		} else {
			sig = append(sig, p.name+" "+typ)
		}
		args = append(args, arg)
	}
	recvType := t.name
	recv := t.recv
	retType := "*" + t.name
	var b strings.Builder
	for _, d := range m.doc {
		b.WriteString(d + "\n")
	}
	var results string
	switch {
	case m.chain:
		results = " " + retType
	case len(m.results) == 1:
		results = " " + m.results[0]
	case len(m.results) > 1:
		results = " (" + strings.Join(m.results, ", ") + ")"
	}
	_ = recvType
	fmt.Fprintf(&b, "func (%s) %s(%s)%s {\n", recv, m.name, strings.Join(sig, ", "), results)
	for _, p := range pre {
		b.WriteString("\t" + p + "\n")
	}
	call := fmt.Sprintf("%s.%s(%s)", t.acc, m.name, strings.Join(args, ", "))
	switch {
	case m.chain:
		fmt.Fprintf(&b, "\t%s\n\treturn %s\n", call, t.ret)
	case len(m.results) == 0:
		fmt.Fprintf(&b, "\t%s\n", call)
	default:
		fmt.Fprintf(&b, "\treturn %s\n", call)
	}
	b.WriteString("}\n")
	return b.String(), nil
}
